  html, body, body.magritte-hh-day-theme, :root {
    /* surfaces */
    --magritte-color-background-primary-v24-7-0: #14181d;
    --magritte-color-background-primary-v21-1-0: #14181d;
    --magritte-color-background-secondary-v24-7-0: #1c2128;
    --magritte-color-background-secondary-v21-1-0: #1c2128;
    --magritte-color-background-tertiary-v24-7-0: #21262d;
    --magritte-color-background-tertiary-v21-1-0: #21262d;
    /* primary text */
    --magritte-color-text-primary-v24-7-0: #e6edf3;
    --magritte-color-text-primary-v21-1-0: #e6edf3;
    /* secondary / tertiary text */
    --magritte-color-text-secondary-v24-7-0: #8b949e;
    --magritte-color-text-secondary-v21-1-0: #8b949e;
    --magritte-color-text-tertiary-v24-7-0: #6e7681;
    --magritte-color-text-tertiary-v21-1-0: #6e7681;
